package com.gathin.tvhome;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;
final class DesktopAppearance {
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("desktop_appearance",0);}
 static int text(Context c){return prefs(c).getInt("text",Color.WHITE);}
 static void apply(View v){if(v instanceof TextView)((TextView)v).setTextColor(text(v.getContext()));if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)apply(((ViewGroup)v).getChildAt(i));v.invalidate();}
 static void slider(Activity a,String title,String key,int initial,Runnable saved){
 LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(36,20,36,20);TextView label=new TextView(a);label.setText(title+"："+initial+"%");box.addView(label);SeekBar bar=new SeekBar(a);bar.setMax(100);bar.setProgress(initial);bar.setKeyProgressIncrement(1);bar.setFocusableInTouchMode(true);box.addView(bar,new LinearLayout.LayoutParams(-1,80));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean u){label.setText(title+"："+n+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});new AlertDialog.Builder(a).setTitle(title).setView(box).setNegativeButton(DesktopLanguage.t(a,"取消"),null).setPositiveButton(DesktopLanguage.t(a,"保存"),(d,w)->{prefs(a).edit().putInt(key,bar.getProgress()).apply();saved.run();}).show();bar.requestFocus();
 }
 static void picker(Activity a,String title,String key,int fallback,Runnable saved){
 float[] hsv=new float[3];Color.colorToHSV(prefs(a).getInt(key,fallback),hsv);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(36,20,36,20);TextView preview=new TextView(a);preview.setTextSize(24);preview.setPadding(20,12,20,12);box.addView(preview);SeekBar[] bars=new SeekBar[3];String[] names={DesktopLanguage.t(a,"色相 H"),DesktopLanguage.t(a,"饱和度 S"),DesktopLanguage.t(a,"明度 V")};TextView[] labels=new TextView[3];Runnable refresh=()->{int color=Color.HSVToColor(hsv);preview.setBackgroundColor(color);preview.setTextColor(hsv[2]>.65f&&hsv[1]<.5f?Color.BLACK:Color.WHITE);preview.setText(String.format(DesktopLanguage.t(a,"文字 / 频谱预览  #%06X"),color&0xffffff));for(int j=0;j<3;j++)if(labels[j]!=null)labels[j].setText(names[j]+"："+Math.round(j==0?hsv[j]:hsv[j]*100));};
 for(int i=0;i<3;i++){final int index=i;labels[i]=new TextView(a);box.addView(labels[i]);SeekBar b=new SeekBar(a);bars[i]=b;b.setMax(i==0?360:100);b.setProgress(Math.round(i==0?hsv[i]:hsv[i]*100));b.setKeyProgressIncrement(i==0?3:1);b.setFocusableInTouchMode(true);
 int[] colors=i==0?new int[]{Color.RED,Color.YELLOW,Color.GREEN,Color.CYAN,Color.BLUE,Color.MAGENTA,Color.RED}:i==1?new int[]{Color.WHITE,Color.HSVToColor(new float[]{hsv[0],1,1})}:new int[]{Color.BLACK,Color.HSVToColor(new float[]{hsv[0],hsv[1],1})};
 android.graphics.drawable.GradientDrawable track=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.LEFT_RIGHT,colors);track.setCornerRadius(8);track.setSize(400,12);b.setProgressDrawable(track);
 box.addView(b,new LinearLayout.LayoutParams(-1,64));b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar v,int n,boolean u){hsv[index]=index==0?n:n/100f;refresh.run();}public void onStartTrackingTouch(SeekBar v){}public void onStopTrackingTouch(SeekBar v){}});}
 refresh.run();AlertDialog dialog=new AlertDialog.Builder(a).setTitle(title+" · HSV").setView(box).setNegativeButton(DesktopLanguage.t(a,"取消"),null).setNeutralButton(DesktopLanguage.t(a,"恢复默认"),(d,w)->{prefs(a).edit().remove(key).apply();saved.run();}).setPositiveButton(DesktopLanguage.t(a,"保存"),(d,w)->{prefs(a).edit().putInt(key,Color.HSVToColor(hsv)).apply();saved.run();}).create();dialog.show();dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0xFF202830));bars[0].requestFocus();
 }
}
